197|     * @return Collection<int>
198|     */
199|    public static function ancestorIds(array $unitIds): Collection
200|    {
201|        $ids = array_values(array_filter($unitIds));
202|
203|        if (empty($ids)) {
204|            return collect();
205|        }
206|
207|        // Cache by sorted IDs to get consistent results regardless of input order
208|        $cache = app(CacheInvalidationServiceInterface::class);
209|        $version = $cache->getVersion('unit_hierarchy');
210|        $sorted = array_map('strval', $ids);
211|        sort($sorted, SORT_STRING);
212|        $cacheKey = 'unit_ancestors:v'.$version.':'.md5(implode(',', $sorted));
213|
214|        return Cache::remember(
215|            $cacheKey,
216|            now()->addMinutes(15), // Same TTL as descendantIds
217|            fn () => self::ancestorQuery($ids)
218|        );
219|    }
