221|    /**
222|     * Run the JOIN query for ancestor IDs.
223|     */
224|    protected static function ancestorQuery(array $ids): Collection
225|    {
226|        $placeholders = implode(',', array_fill(0, count($ids), '?'));
227|
228|        $results = DB::select("
229|            SELECT DISTINCT parent.id
230|            FROM units base
231|            INNER JOIN units parent ON parent.id = base.parent_id
232|            WHERE base.id IN ({$placeholders})
233|        ", $ids);
234|
235|        return collect($results)->pluck('id');
236|    }
237|
238|    /**
239|     * تمام id های زیرمجموعه (شامل خود واحدهای ورودی) با Recursive CTE
240|     *
241|     * @param  int|array<int>  $unitIds
242|     */
243|    public static function descendantIds(int|array $unitIds): Collection
244|    {
245|        $ids = is_array($unitIds) ? $unitIds : [$unitIds];
246|
247|        if (empty($ids)) {
248|            return collect();
249|        }
250|
251|        // Cache by sorted IDs to get consistent results regardless of input order
252|        $cache = app(CacheInvalidationServiceInterface::class);
253|        $version = $cache->getVersion('unit_hierarchy');
254|        $sorted = array_map('strval', $ids);
255|        sort($sorted, SORT_STRING);
256|        $cacheKey = 'unit_descendants:v'.$version.':'.md5(implode(',', $sorted));
257|
258|        return Cache::remember(
259|            $cacheKey,
260|            now()->addMinutes(15), // Shorter TTL to catch changes faster
261|            fn () => self::recursiveDescendantQuery($ids)
262|        );
263|    }
264|
265|    /**
266|     * Run the recursive CTE query for descendant IDs.
267|     *
268|     * UNION (not UNION ALL) is load-bearing: the set operator dedupes, so a
269|     * parent_id cycle terminates instead of recursing forever. UNION ALL on a
270|     * cyclic parent_id hangs the connection — parent_id is user-editable and
271|     * not constrained by the database, so the web form's type guard is not the
272|     * only possible writer.
273|     */
274|    protected static function recursiveDescendantQuery(array $ids): Collection
275|    {
276|        $placeholders = implode(',', array_fill(0, count($ids), '?'));
277|
278|        $results = DB::select("
279|            WITH RECURSIVE unit_tree AS (
280|                SELECT id FROM units WHERE id IN ({$placeholders})
281|                UNION
282|                SELECT u.id FROM units u
283|                INNER JOIN unit_tree ut ON u.parent_id = ut.id
284|                WHERE u.is_active = true
285|            )
286|            SELECT id FROM unit_tree
287|        ", $ids);
288|
289|        return collect($results)->pluck('id');
290|    }
