306|    public function scopeNearby($query, float $lat, float $lng, float $radiusKm = 10)
307|    {
308|        // Approximate degrees per km (rough estimate for Iran region)
309|        $degPerKm = 0.009;
310|        $delta = $radiusKm * $degPerKm;
311|
312|        return $query->whereBetween('lat', [$lat - $delta, $lat + $delta])
313|            ->whereBetween('lng', [$lng - $delta, $lng + $delta]);
314|    }
315|
316|    /**
317|     * Scope for spatial queries: find units whose boundary contains a point
318|     * Uses the spatial index on boundaries.boundary
319|     * Optimized with EXISTS to better utilize spatial index
320|     */
321|    public function scopeContainingPoint($query, float $lat, float $lng)
322|    {
323|        // The unit↔boundary link is units.boundary_id (boundaries has no unit_id).
324|        return $query->whereHas('boundary', function ($q) use ($lat, $lng) {
325|            $q->whereRaw('ST_Contains(boundary, ST_GeomFromText(?, 4326))', ["POINT($lng $lat)"]);
326|        });
327|    }
328|
329|    /**
330|     * Scope for spatial queries: find units whose boundary intersects with a polygon
331|     * Uses the spatial index on boundaries.boundary
332|     */
333|    public function scopeIntersectsBoundary($query, string $wktPolygon)
334|    {
335|        return $query->whereHas('boundary', function ($q) use ($wktPolygon) {
336|            $q->whereRaw('ST_Intersects(boundary, ST_GeomFromText(?, 4326))', [$wktPolygon]);
337|        });
338|    }
339|
340|    /**
