15|    public function index(UnitScopedRequest $request): JsonResponse
16|    {
17|        $accessibleIds = $request->accessibleIds();
18|
19|        $query = Person::whereIn('u_id', $accessibleIds)
20|            ->with(['unit:id,name', 'semat:id,name', 'tahsil:id,name', 'estekhdam:id,name', 'radif:id,name']);
21|
22|        if ($request->filled('search')) {
23|            $s = self::normalizeForQuery($request->search);
24|            $query->where(function ($q) use ($s) {
25|                $q->where('n_code', 'LIKE', "%{$s}%")
26|                    ->orWhere('f_name', 'LIKE', "%{$s}%")
27|                    ->orWhere('l_name', 'LIKE', "%{$s}%")
28|                    ->orWhereRaw("CONCAT(f_name, ' ', l_name) LIKE ?", ["%{$s}%"]);
29|            });
30|        }
31|
32|        if ($request->filled('unit_id')) {
33|            $query->where('u_id', $request->unit_id);
34|        }
35|
36|        if ($request->filled('semat_id')) {
37|            $query->where('s_id', $request->semat_id);
38|        }
39|
40|        $allowedSortColumns = ['n_code', 'f_name', 'l_name', 'created_at', 'u_id', 's_id', 't_id', 'e_id', 'r_id'];
41|        $sortBy = $request->get('sort_by', 'n_code');
42|        if (! in_array($sortBy, $allowedSortColumns)) {
43|            $sortBy = 'n_code';
44|        }
45|
46|        $sortDir = strtolower($request->get('sort_dir', 'asc'));
47|        if (! in_array($sortDir, ['asc', 'desc'])) {
48|            $sortDir = 'asc';
49|        }
50|
51|        $query->orderBy($sortBy, $sortDir);
52|
53|        $perPage = min((int) $request->get('per_page', 20), 100);
54|        $persons = $query->paginate($perPage);
55|
56|        return response()->json([
57|            'data' => $persons->items(),
58|            'meta' => [
59|                'current_page' => $persons->currentPage(),
60|                'last_page' => $persons->lastPage(),
61|                'per_page' => $persons->perPage(),
62|                'total' => $persons->total(),
63|            ],
64|        ]);
65|    }
66|
67|    public function show(UnitScopedRequest $request, Person $person): JsonResponse
68|    {
69|        $accessibleIds = $request->accessibleIds();
70|
71|        if (! in_array($person->u_id, $accessibleIds)) {
72|            return response()->json(['message' => 'Person not accessible.'], 403);
73|        }
74|
75|        return response()->json([
76|            'data' => $person->load(['unit:id,name', 'semat:id,name', 'tahsil:id,name', 'estekhdam:id,name', 'radif:id,name']),
77|        ]);
