81|    {
82|        $validated = $request->validate([
83|            'n_code' => 'required|string|size:10|unique:persons,n_code',
84|            'f_name' => 'required|string|max:255',
85|            'l_name' => 'required|string|max:255',
86|            't_id' => 'required|exists:tahsils,id',
87|            'e_id' => 'required|exists:estekhdams,id',
88|            's_id' => 'required|exists:semats,id',
89|            'r_id' => 'required|exists:radifs,id',
90|            'u_id' => 'required|exists:units,id',
91|        ]);
92|
93|        $accessibleIds = $request->accessibleIds();
94|
95|        if (! in_array($validated['u_id'], $accessibleIds)) {
96|            return response()->json(['message' => 'Unit not accessible.'], 403);
97|        }
98|
99|        $person = Person::create($validated);
100|
101|        return response()->json([
102|            'success' => true,
103|            'data' => $person->load(['unit:id,name', 'semat:id,name']),
104|        ], 201);
