109|        $accessibleIds = $request->accessibleIds();
110|
111|        if (! in_array($person->u_id, $accessibleIds)) {
112|            return response()->json(['message' => 'Person not accessible.'], 403);
113|        }
114|
115|        // Issue #532: validate FIRST, then check scope — prevents information
116|        // disclosure through differential error responses (403 vs 422).
117|        $validated = $request->validate([
118|            'n_code' => 'sometimes|required|string|size:10|unique:persons,n_code,'.$person->n_code.',n_code',
119|            'f_name' => 'sometimes|required|string|max:255',
120|            'l_name' => 'sometimes|required|string|max:255',
121|            't_id' => 'sometimes|required|exists:tahsils,id',
122|            'e_id' => 'sometimes|required|exists:estekhdams,id',
123|            's_id' => 'sometimes|required|exists:semats,id',
124|            'r_id' => 'sometimes|required|exists:radifs,id',
125|            'u_id' => 'sometimes|required|exists:units,id',
126|        ]);
127|
128|        if (isset($validated['u_id']) && ! in_array($validated['u_id'], $accessibleIds)) {
