12|{
13|    public function index(UnitScopedRequest $request): array
14|    {
15|        $ids = $request->accessibleIds();
16|        $perPage = min($request->integer('per_page', 15), 100);
17|        $units = Unit::whereIn('id', $ids)
18|            ->with('unitType:id,name')
19|            ->paginate($perPage);
20|
21|        return [
22|            'data' => $units->items(),
23|            'meta' => [
24|                'current_page' => $units->currentPage(),
