26|                'per_page' => $units->perPage(),
27|                'total' => $units->total(),
28|            ],
29|        ];
30|    }
31|
32|    public function show(UnitScopedRequest $request, Unit $unit): JsonResponse
33|    {
34|        $ids = $request->accessibleIds();
35|
36|        if (! in_array($unit->id, $ids)) {
37|            return response()->json(['message' => 'Unit not accessible.'], 403);
38|        }
39|
40|        return response()->json([
41|            'data' => $unit->load('unitType:id,name', 'region:id,name', 'parent:id,name'),
42|        ]);
43|    }
44|
45|    public function store(UnitScopedRequest $request): JsonResponse
46|    {
47|        $validated = $request->validate([
48|            'name' => 'required|string|max:255',
49|            'description' => 'nullable|string',
50|            'region_id' => 'nullable|exists:regions,id',
51|            'parent_id' => 'nullable|exists:units,id',
52|            'unit_type_id' => 'required|exists:unit_types,id',
53|            'lat' => 'nullable|numeric|between:-90,90',
54|            'lng' => 'nullable|numeric|between:-180,180',
55|        ]);
56|
57|        // Check organizational scope for parent_id and region_id
58|        $accessibleIds = $request->accessibleIds();
59|
60|        if (! empty($validated['parent_id']) && ! in_array($validated['parent_id'], $accessibleIds)) {
61|            return response()->json(['message' => 'Parent unit not accessible.'], 403);
62|        }
63|
64|        $unit = Unit::create($validated);
65|
66|        // Invalidate AccessService cache if hierarchy changed (new child created)
67|        if (! empty($unit->parent_id)) {
68|            app(AccessService::class)->clearAllCaches();
69|        }
70|
71|        return response()->json([
72|            'success' => true,
73|            'data' => $unit,
74|        ], 201);
75|    }
76|
77|    public function update(UnitScopedRequest $request, Unit $unit): JsonResponse
78|    {
79|        $ids = $request->accessibleIds();
80|
81|        if (! in_array($unit->id, $ids)) {
82|            return response()->json(['message' => 'Unit not accessible.'], 403);
83|        }
84|
85|        $validated = $request->validate([
86|            'name' => 'sometimes|required|string|max:255',
87|            'description' => 'nullable|string',
88|            'region_id' => 'nullable|exists:regions,id',
89|            'parent_id' => 'nullable|exists:units,id',
90|            'unit_type_id' => 'sometimes|required|exists:unit_types,id',
91|            'lat' => 'nullable|numeric|between:-90,90',
92|            'lng' => 'nullable|numeric|between:-180,180',
93|        ]);
94|
95|        // Check organizational scope for parent_id
96|        $accessibleIds = $request->accessibleIds();
97|
98|        if (! empty($validated['parent_id']) && ! in_array($validated['parent_id'], $accessibleIds)) {
99|            return response()->json(['message' => 'Parent unit not accessible.'], 403);
100|        }
101|
102|        $oldParentId = $unit->parent_id; // Capture before update for hierarchy-change detection (#371)
103|
104|        // Prevent hierarchy cycles: parent cannot be the unit itself or one of its descendants (#324)
105|        if (empty($validated['parent_id'])) {
106|            $unit->update($validated);
107|        } else {
108|            $forbiddenIds = Unit::descendantIds($unit->id)->push($unit->id)->all();
109|            if (in_array($validated['parent_id'], $forbiddenIds)) {
110|                return response()->json(['message' => 'Cannot set a descendant or self as parent (would create a cycle).'], 422);
111|            }
112|            $unit->update($validated);
113|        }
114|
115|        // Check if hierarchy is being changed (compare against pre-update value)
116|        $hierarchyChanged = $request->has('parent_id') && $request->input('parent_id') !== $oldParentId;
117|
118|        // Invalidate AccessService cache for all users if hierarchy changed
119|        if ($hierarchyChanged) {
120|            app(AccessService::class)->clearAllCaches();
121|        }
122|
123|        return response()->json([
124|            'success' => true,
125|            'data' => $unit->fresh(),
126|        ]);
127|    }
128|
129|    public function destroy(UnitScopedRequest $request, Unit $unit): JsonResponse
130|    {
131|        $ids = $request->accessibleIds();
132|
133|        if (! in_array($unit->id, $ids)) {
134|            return response()->json(['message' => 'Unit not accessible.'], 403);
135|        }
136|
137|        if ($unit->children()->exists()) {
138|            return response()->json(['message' => 'Cannot delete unit with children.'], 422);
139|        }
140|
141|        // Invalidate AccessService cache as hierarchy is changing
142|        app(AccessService::class)->clearAllCaches();
143|
144|        $unit->delete();
145|
146|        return response()->json(['success' => true]);
147|    }
